style.css:
@-moz-document domain("mail.google.com") {
body {
    background: url("https://i.imgur.com/fs1s6Bc.png") center center fixed no-repeat !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  /* Make Gmail panels slightly transparent for readability */
  .aeF, .AO, .nH {
    background-color: rgba(255, 255, 255, 0.85) !important;
  }

  /* Optional: hide Gmail’s default background tint */
  .aic, .aeJ {
    background: transparent !important;
  }
}
